```rust
// Import necessary types for a vector (array-like) and a hash map (dictionary).
use std::collections::HashMap;

/// Function to find the first inversion in a vector and swap it.
///
/// # Arguments
/// * `arr`: A mutable vector of `i32` (or any comparable type).
///
/// # Returns
/// A `HashMap` with keys:
/// * `"index"`: 1-based index of the element that was out of order (or -1 if none)
/// * `"swap_with"`: 1-based index of the element it was swapped with (or -1 if none)
/// * `"num_swaps"`: Number of swaps performed (always 1 if swap happened, else 0)
fn can_arrange(arr: &mut Vec<i32>) -> HashMap<String, i32> {
    // Start swap counter at 0
    let mut num_swaps = 0;
    let mut found = false; // Track if we found and swapped anything

    // Iterate over indices except the last one
    for i in 0..arr.len() - 1 {
        // Check for inversion: current element > next element
        if arr[i] > arr[i + 1] {
            // Increment swap counter
            num_swaps += 1;

            // Swap the two elements
            arr.swap(i, i + 1);

            // Return immediately with the required info (1-based index)
            return HashMap::new() [
                ("index".to_string(), (i + 1) as i32),
                ("swap_with".to_string(), (i + 1) as i32),
                ("num_swaps".to_string(), num_swaps as i32),
            ];
        }
    }

    // If no inversion found, return default result
    return HashMap::new() [
        ("index".to_string(), -1),
        ("swap_with".to_string(), -1),
        ("num_swaps".to_string(), 0),
    ];
}
```

