using System;
using System.Collections.Generic;

// Helper: factorial_or_sum
int factorial_or_sum(int n)
{
    if (n == 0)
        return 0;
    else if (n == 1)
        return 1;
    else
    {
        int factorial = 1;
        int sum = 0;
        for (int i = 2; i <= n; i++)
        {
            factorial *= i;
            sum += i;
        }
        return (factorial < sum) ? factorial : sum;
    }
}

// Helper: Fibonacci
int fibonacci(int n)
{
    if (n == 0)
        return 0;
    else if (n == 1)
        return 1;
    else
    {
        int a = 0, b = 1;
        for (int i = 2; i <= n; i++)
        {
            int next = a + b;
            a = b;
            b = next;
        }
        return b;
    }
}

// Main function f
List<Tuple<int, int?>> f(int n, int m)
{
    List<Tuple<int, int?>> results = new List<Tuple<int, int?>>();

    // First part: 1..n
    for (int i = 1; i <= n; i++)
    {
        int fs = factorial_or_sum(i);
        int fb = fibonacci(i);
        results.Add(new Tuple<int, int?>((fs, fb)));
    }

    // Second part: n+1 .. m (if any)
    if (m > n)
    {
        for (int i = n + 1; i <= m; i++)
        {
            results.Add(null);
        }
    }

    return results;
}

